Menu Driven Problem <p>Write a menu driven program which has    following options:    1. Positive or negative   2. Factorial of a number   3. Odd or even   4. Exit</p> <pre><code>#include &lt;stdio.h&gt;

int main() {
    int choice, num, i, fact;

    while (1) {
        printf("\n----- MENU -----\n");
        printf("1. Positive or Negative\n");
        printf("2. Factorial of a Number\n");
        printf("3. Odd or Even\n");
        printf("4. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &amp;choice);

        switch (choice) {

            case 1:
                printf("Enter a number: ");
                scanf("%d", &amp;num);

                if (num &gt; 0)
                    printf("The number is Positive\n");
                else if (num &lt; 0)
                    printf("The number is Negative\n");
                else
                    printf("The number is Zero\n");
                break;

            case 2:
                printf("Enter a number: ");
                scanf("%d", &amp;num);

                fact = 1;
                for (i = 1; i &lt;= num; i++) {
                    fact = fact * i;
                }

                printf("Factorial of %d is %d\n", num, fact);
                break;

            case 3:
                printf("Enter a number: ");
                scanf("%d", &amp;num);

                if (num % 2 == 0)
                    printf("The number is Even\n");
                else
                    printf("The number is Odd\n");
                break;

            case 4:
                printf("Exiting program...\n");
                return 0;

            default:
                printf("Invalid choice. Try again.\n");
        }
    }

    return 0;
}
</code></pre>

Stack <pre><code>    #include &lt;stdio.h&gt;

    int arr[5];
    int top = 0;

    /* Function to check if stack is full */
    int isFull() {
        if (top == 5) {
            return 1;   // true
        }
        return 0;       // false
    }

    /* Function to check if stack is empty */
    int isEmpty() {
        if (top == 0) {
            return 1;   // true
        }
        return 0;       // false
    }

    /* Push operation */
    void push(int item) {
        if (isFull()) {
            printf("Stack is full\n");
        } else {
            printf("Now inserting %d\n", item);
            arr[top] = item;
            top++;
        }
    }

    /* Pop operation */
    void pop() {
        if (isEmpty()) {
            printf("No data in stack\n");
        } else {
            top--;
            printf("%d\n", arr[top]);
        }
    }

    int main() {
        push(10);
        push(7);
        push(5);
        push(11);
        push(122);
        push(1);

        pop();
        pop();
        pop();
        pop();
        pop();
        pop();

        return 0;
    }
</code></pre>
